INSERT INTO sources(source_key,title,title_fa,organization_or_author,language_code,source_type,url,locator,locator_fa,published_or_updated_at,modernity_status,currency_evidence,license_name,license_url,attribution_text,reuse_status,retrieved_at,notes) VALUES
('src-wikibooks-de-lesson-002-service-clarification','Deutschkurs für Anfänger/Lektion 002','درخواست تکرار و آهسته‌تر گفتن','Wikibooks contributors','de','course','https://en.wikibooks.org/wiki/Deutschkurs_f%C3%BCr_Anf%C3%A4nger/Lektion_002','Item 075 and vocabulary: asking for repetition and slower speech.','بخش ۰۷۵؛ درخواست تکرار و آهسته‌تر گفتن.','2023-12-13','contemporary_verified','صفحهٔ زندهٔ ویکی‌بوکس در ۱۸ سپتامبر ۲۰۲۶ بررسی شد؛ آخرین ویرایش صفحه ۱۳ دسامبر ۲۰۲۳ ثبت شده است. عبارت انتخاب‌شده برای درخواست تکرار و آهسته‌تر گفتن در بازبینی فعلی همچنان طبیعی و کاربردی است.','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0/','Wikibooks contributors — Deutschkurs für Anfänger/Lektion 002','reuse_with_attribution','2026-09-18','استفاده در این واحد به عبارت بخش ۰۷۵ برای درخواست تکرار و آهسته‌تر گفتن محدود است.'),
('src-wikivoyage-german-phrasebook-services','German phrasebook — Basics and Problems','عبارت‌های خدمات، کمک و اجازه','Wikivoyage contributors','de','website','https://en.wikivoyage.org/wiki/German_phrasebook','Basics and Problems sections: English question, understanding, help, phone permission, toilet and pharmacy.','بخش‌های پایه و مشکلات؛ زبان، فهم، کمک، تلفن، سرویس بهداشتی و داروخانه.',NULL,'maintained_current','بخش‌های پایه و مشکلات در عبارت‌نامهٔ آلمانی ویکی‌ویاژ در ۱۸ سپتامبر ۲۰۲۶ بررسی شدند. پرسش دربارهٔ انگلیسی، بیان نفهمیدن، درخواست کمک، اجازهٔ استفاده از تلفن، سرویس بهداشتی و داروخانه در نسخهٔ فعلی صفحه حضور دارند.','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0/','Wikivoyage contributors — German phrasebook','reuse_with_attribution','2026-09-18','در گزینه‌هایی که منبع دو شکل دوستانه و رسمی را کنار هم نوشته، این واحد فقط شکل رسمی را انتخاب می‌کند و این انتخاب در ردگیری منبع ثبت می‌شود.')
INSERT INTO source_items(source_id,item_key,locator,locator_fa,source_text,source_text_hash,notes) VALUES
(@sb,'srcitem-de-a1-service-repeat','075','بخش ۰۷۵','Wie bitte? Noch einmal, bitte langsam.',UNHEX(SHA2('Wie bitte? Noch einmal, bitte langsam.',256)),'درخواست تکرار و آهسته‌تر گفتن.'),
(@sv,'srcitem-de-a1-service-english','Basics','بخش پایه','Sprechen Sie Englisch?',UNHEX(SHA2('Sprechen Sie Englisch?',256)),'پرسش رسمی دربارهٔ زبان انگلیسی.'),
(@sv,'srcitem-de-a1-service-understand','Basics','بخش پایه','Ich verstehe das nicht.',UNHEX(SHA2('Ich verstehe das nicht.',256)),'بیان نفهمیدن.'),
(@sv,'srcitem-de-a1-service-toilet','Basics','بخش پایه','Wo ist die Toilette, bitte?',UNHEX(SHA2('Wo ist die Toilette, bitte?',256)),'پرسش خدماتی.'),
(@sv,'srcitem-de-a1-service-help','Problems','بخش مشکلات','Ich brauche deine/Ihre Hilfe.',UNHEX(SHA2('Ich brauche deine/Ihre Hilfe.',256)),'منبع دو شکل دوستانه و رسمی را کنار هم دارد.'),
(@sv,'srcitem-de-a1-service-phone','Problems','بخش مشکلات','Kann ich dein/Ihr Telefon benutzen?',UNHEX(SHA2('Kann ich dein/Ihr Telefon benutzen?',256)),'منبع دو شکل دوستانه و رسمی را کنار هم دارد.'),
(@sv,'srcitem-de-a1-service-apotheke','At the doctor','بخش پزشک','Apotheke',UNHEX(SHA2('Apotheke',256)),'واژهٔ داروخانه.')
INSERT INTO units(unit_key,language_level_id,sequence_index,title_fa,grouping_rationale,status,metadata,notes) VALUES
('de-a1-unit-requests-services-help',@level,9,'درخواست، اجازه و خدمات روزمره','این واحد توانایی‌های بقای سطح پیشین را از عبارت‌های ثابت به مدیریت یک مشکل ارتباطی ساده گسترش می‌دهد: روشن‌سازی، اجازه گرفتن و درخواست کمک مشخص. یک درس پنج‌فعالیتی این سه کارکرد را بدون ساخت درس‌های تکراری پوشش می‌دهد.','review',JSON_OBJECT('sourceRefs',JSON_ARRAY('src-wikibooks-de-lesson-002-service-clarification','src-wikivoyage-german-phrasebook-services'),'learningTargets',JSON_ARRAY('درخواست تکرار و آهسته‌تر گفتن','اجازهٔ ساده','درخواست کمک مشخص','واژگان خدمات پایه')),'بازبینی پوشش انجام شد. درخواست تکرار و آهسته‌تر گفتن، اجازهٔ استفاده از تلفن، درخواست کمک و واژگان خدمات پایه پوشش دارند؛ برای هدف فعلی خدمات و کمک شکاف ضروری مستقلی برای درس دوم دیده نشد.')
