('lex-de-telefon',@de,'word','Telefon','Telefon','Telefon','noun','اسم','A1','تلفن','در پرسش اجازهٔ استفاده از تلفن آمده است.',TRUE,'blocked_until_level_final'),
('lex-de-benutzen',@de,'word','benutzen','benutzen','benutzen','verb','فعل','A1','استفاده کردن','در پرسش اجازهٔ استفاده از تلفن به کار می‌رود.',TRUE,'blocked_until_level_final'),
