('lex-de-verstehen',@de,'word','verstehen','verstehen','verstehen','verb','فعل','A1','فهمیدن','برای گفتن اینکه چیزی را نمی‌فهمیم استفاده می‌شود.',TRUE,'blocked_until_level_final')
INSERT INTO lessons(lesson_key,language_level_id,unit_id,sequence_index,position_in_unit,title_fa,source_title,source_title_fa,status,activity_selection_rationale,sequence_rationale,template_signature,audio_status,notes) VALUES
('de-a1-lesson-clarify-permission-help',@level,@unit,14,1,'لطفاً یک بار دیگر، آهسته','Noch einmal, bitte langsam. / Kann ich Ihr Telefon benutzen?','یک بار دیگر، لطفاً آهسته / می‌توانم از تلفن شما استفاده کنم؟','draft','گفت‌وگو درخواست تکرار را در بافت واقعی تمرین می‌کند؛ سپس اجازهٔ استفاده از تلفن، درخواست کمک، واژگان خدمات و در پایان بازسازی عبارت تکرار پوشش داده می‌شوند.','درس از یک مشکل فهم واقعی به تشخیص اجازه و کمک، تثبیت واژگان خدمات و بازیابی فعال درخواست روشن‌سازی حرکت می‌کند.','conversation_speaking>multiple_choice>choose_response>matching>word_order','blocked_until_level_final','یک درس پنج‌فعالیتی برای پوشش روشن‌سازی، اجازه و کمک مشخص کافی است.')
