INSERT INTO dialogues(dialogue_key,language_level_id,scenario,opening_initiator,scene_quality_rationale) VALUES
('dlg-de-a1-clarify-slowly',@level,'آیریس یک پرسش ساده به پاول می‌گوید؛ پاول درخواست می‌کند دوباره و آهسته‌تر گفته شود و آیریس همان پرسش منبع‌دار را تکرار می‌کند.','app','تکرار دقیق پرسش پس از درخواست «یک بار دیگر، لطفاً آهسته» بخشی طبیعی از خود سناریوی روشن‌سازی است. هیچ جملهٔ آلمانی تازه ساخته نشده و دو منبع فقط در یک تعامل کوتاه کنار هم قرار گرفته‌اند.')
