INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-service-conversation',@lesson,1,'conversation_speaking','اگر پرسش را نفهمیدی، بخواه یک بار دیگر و آهسته گفته شود.','سه نوبت منبع‌دار یک چرخهٔ طبیعی پرسش، درخواست تکرار و تکرار همان پرسش را می‌سازند.',@dialogue,JSON_OBJECT('interaction','read_aloud_exchange','openingInitiator','app'),JSON_ARRAY('other','persian_translation_added','character_metadata_added'),NULL,'not_required'),
('act-de-a1-phone-permission-choice',@lesson,2,'multiple_choice','کدام عبارت برای اجازه گرفتنِ استفاده از تلفن است؟','شکل رسمی از گزینهٔ رسمی منبع انتخاب شده و با دو پرسش خدماتی دیگر مقایسه می‌شود.',NULL,JSON_OBJECT('options',JSON_ARRAY(JSON_OBJECT('textTarget','Kann ich Ihr Telefon benutzen?','translationFa','می‌توانم از تلفن شما استفاده کنم؟','correct',TRUE),JSON_OBJECT('textTarget','Wo ist die Toilette, bitte?','translationFa','سرویس بهداشتی کجاست، لطفاً؟','correct',FALSE),JSON_OBJECT('textTarget','Sprechen Sie Englisch?','translationFa','انگلیسی صحبت می‌کنید؟','correct',FALSE))),JSON_ARRAY('options_selected_from_source_material','other','persian_translation_added'),NULL,'not_required'),
('act-de-a1-specific-help-response',@lesson,3,'choose_response','در پاسخ به «چه چیزی لازم دارید؟» کدام جمله مستقیم می‌گوید به کمک نیاز داری؟','عبارت رسمی درخواست کمک از منبع خدمات با دو عبارت نامرتبط همان منبع مقایسه می‌شود.',NULL,JSON_OBJECT('promptTarget','Was brauchen Sie?','promptFa','چه چیزی لازم دارید؟','options',JSON_ARRAY(JSON_OBJECT('textTarget','Ich brauche Ihre Hilfe.','translationFa','به کمک شما نیاز دارم.','correct',TRUE),JSON_OBJECT('textTarget','Ich verstehe das nicht.','translationFa','این را نمی‌فهمم.','correct',FALSE),JSON_OBJECT('textTarget','Wo ist die Toilette, bitte?','translationFa','سرویس بهداشتی کجاست، لطفاً؟','correct',FALSE))),JSON_ARRAY('options_selected_from_source_material','other','persian_translation_added'),NULL,'not_required'),
('act-de-a1-service-words-matching',@lesson,4,'matching','هر واژهٔ خدماتی را به معنی درستش وصل کن.','دو واژهٔ آشنا و دو واژهٔ تازه در یک شبکهٔ خدمات روزمره تثبیت می‌شوند.',NULL,JSON_OBJECT('pairs',JSON_ARRAY(JSON_OBJECT('left','Hilfe','leftFa','کمک','right','کمک','rightFa','کمک'),JSON_OBJECT('left','Telefon','leftFa','تلفن','right','تلفن','rightFa','تلفن'),JSON_OBJECT('left','Toilette','leftFa','سرویس بهداشتی','right','سرویس بهداشتی','rightFa','سرویس بهداشتی'),JSON_OBJECT('left','Apotheke','leftFa','داروخانه','right','داروخانه','rightFa','داروخانه'))),JSON_ARRAY('source_items_grouped_for_matching','persian_translation_added'),NULL,'not_required'),
('act-de-a1-repeat-slowly-order',@lesson,5,'word_order','درخواست تکرار و آهسته‌تر گفتن را دوباره بساز.','عبارت کلیدی گفت‌وگو در پایان به بازیابی فعال منتقل می‌شود.',NULL,JSON_OBJECT('sourceText','Wie bitte? Noch einmal, bitte langsam.','sourceTextFa','ببخشید؟ یک بار دیگر، لطفاً آهسته.','tokens',JSON_ARRAY('Wie','bitte?','Noch','einmal,','bitte','langsam.'),'answer',JSON_ARRAY('Wie','bitte?','Noch','einmal,','bitte','langsam.')),JSON_ARRAY('sentence_tokenized_for_word_order','persian_translation_added'),NULL,'not_required')
